220  void Parser::Parse() {
   221      AI_ASE_PARSER_INIT();
   222      while (true) {
   223          if ('*' == *filePtr) {
   224              ++filePtr;
   225
   226              // Version should be 200. Validate this ...
   227              if (TokenMatch(filePtr, "3DSMAX_ASCIIEXPORT", 18)) {
   228                  unsigned int fmt;
   229                  ParseLV4MeshLong(fmt);
   230
   231                  if (fmt > 200) {
   232                      LogWarning("Unknown file format version: *3DSMAX_ASCIIEXPORT should \
   233                                 be <= 200");
   234                  }
   235                  // *************************************************************
   236                  // - fmt will be 0 if we're unable to read the version number
   237                  // there are some faulty files without a version number ...
   238                  // in this case we'll guess the exact file format by looking
   239                  // at the file extension (ASE, ASK, ASC)
   240                  // *************************************************************
   241
   242                  if (fmt) {
   243                      iFileFormat = fmt;
   244                  }
   245                  continue;
   246              }
   247              // main scene information
   248              if (TokenMatch(filePtr, "SCENE", 5)) {
   249                  ParseLV1SceneBlock();
   250                  continue;
   251              }
   252              // "group" - no implementation yet, in facte
   253              // we're just ignoring them for the moment
   254              if (TokenMatch(filePtr, "GROUP", 5)) {
   255                  Parse();
   256                  continue;
   257              }
   258              // material list
   259              if (TokenMatch(filePtr, "MATERIAL_LIST", 13)) {
   260                  ParseLV1MaterialListBlock();
   261                  continue;
   262              }
   263              // geometric object (mesh)
   264              if (TokenMatch(filePtr, "GEOMOBJECT", 10))
   265
   266              {
   267                  m_vMeshes.emplace_back("UNNAMED");
   268                  ParseLV1ObjectBlock(m_vMeshes.back());
   269                  continue;
   270              }
   271              // helper object = dummy in the hierarchy
   272              if (TokenMatch(filePtr, "HELPEROBJECT", 12))
   273
   274              {
   275                  m_vDummies.emplace_back();
   276                  ParseLV1ObjectBlock(m_vDummies.back());
   277                  continue;
   278              }
   279              // light object
   280              if (TokenMatch(filePtr, "LIGHTOBJECT", 11))
   281
   282              {
   283                  m_vLights.emplace_back("UNNAMED");
   284                  ParseLV1ObjectBlock(m_vLights.back());
   285                  continue;
   286              }
   287              // camera object
   288              if (TokenMatch(filePtr, "CAMERAOBJECT", 12)) {
   289                  m_vCameras.emplace_back("UNNAMED");
   290                  ParseLV1ObjectBlock(m_vCameras.back());
   291                  continue;
   292              }
   293              // comment - print it on the console
   294              if (TokenMatch(filePtr, "COMMENT", 7)) {
   295                  std::string out = "<unknown>";
   296                  ParseString(out, "*COMMENT");
   297                  LogInfo(("Comment: " + out).c_str());
   298                  continue;
   299              }
   300              // ASC bone weights
   301              if (AI_ASE_IS_OLD_FILE_FORMAT() && TokenMatch(filePtr, "MESH_SOFTSKINVERTS", 18)) {
   302                  ParseLV1SoftSkinBlock();
   303              }
   304          }
   305          AI_ASE_HANDLE_TOP_LEVEL_SECTION();
   306      }
   307      return;
   308  }
