   779  void Parser::ParseLV1ObjectBlock(ASE::BaseNode &node) {
   780      AI_ASE_PARSER_INIT();
   781      while (true) {
   782          if ('*' == *filePtr) {
   783              ++filePtr;
   784
   785              // first process common tokens such as node name and transform
   786              // name of the mesh/node
   787              if (TokenMatch(filePtr, "NODE_NAME", 9)) {
   788                  if (!ParseString(node.mName, "*NODE_NAME"))
   789                      SkipToNextToken();
   790                  continue;
   791              }
   792              // name of the parent of the node
   793              if (TokenMatch(filePtr, "NODE_PARENT", 11)) {
   794                  if (!ParseString(node.mParent, "*NODE_PARENT"))
   795                      SkipToNextToken();
   796                  continue;
   797              }
   798              // transformation matrix of the node
   799              if (TokenMatch(filePtr, "NODE_TM", 7)) {
   800                  ParseLV2NodeTransformBlock(node);
   801                  continue;
   802              }
   803              // animation data of the node
   804              if (TokenMatch(filePtr, "TM_ANIMATION", 12)) {
   805                  ParseLV2AnimationBlock(node);
   806                  continue;
   807              }
   808
   809              if (node.mType == BaseNode::Light) {
   810                  // light settings
   811                  if (TokenMatch(filePtr, "LIGHT_SETTINGS", 14)) {
   812                      ParseLV2LightSettingsBlock((ASE::Light &)node);
   813                      continue;
   814                  }
   815                  // type of the light source
   816                  if (TokenMatch(filePtr, "LIGHT_TYPE", 10)) {
   817                      if (!ASSIMP_strincmp("omni", filePtr, 4)) {
   818                          ((ASE::Light &)node).mLightType = ASE::Light::OMNI;
   819                      } else if (!ASSIMP_strincmp("target", filePtr, 6)) {
   820                          ((ASE::Light &)node).mLightType = ASE::Light::TARGET;
   821                      } else if (!ASSIMP_strincmp("free", filePtr, 4)) {
   822                          ((ASE::Light &)node).mLightType = ASE::Light::FREE;
   823                      } else if (!ASSIMP_strincmp("directional", filePtr, 11)) {
   824                          ((ASE::Light &)node).mLightType = ASE::Light::DIRECTIONAL;
   825                      } else {
   826                          LogWarning("Unknown kind of light source");
   827                      }
   828                      continue;
   829                  }
   830              } else if (node.mType == BaseNode::Camera) {
   831                  // Camera settings
   832                  if (TokenMatch(filePtr, "CAMERA_SETTINGS", 15)) {
   833                      ParseLV2CameraSettingsBlock((ASE::Camera &)node);
   834                      continue;
   835                  } else if (TokenMatch(filePtr, "CAMERA_TYPE", 11)) {
   836                      if (!ASSIMP_strincmp("target", filePtr, 6)) {
   837                          ((ASE::Camera &)node).mCameraType = ASE::Camera::TARGET;
   838                      } else if (!ASSIMP_strincmp("free", filePtr, 4)) {
   839                          ((ASE::Camera &)node).mCameraType = ASE::Camera::FREE;
   840                      } else {
   841                          LogWarning("Unknown kind of camera");
   842                      }
   843                      continue;
   844                  }
   845              } else if (node.mType == BaseNode::Mesh) {
   846                  // mesh data
   847                  // FIX: Older files use MESH_SOFTSKIN
   848                  if (TokenMatch(filePtr, "MESH", 4) ||
   849                          TokenMatch(filePtr, "MESH_SOFTSKIN", 13)) {
   850                      ParseLV2MeshBlock((ASE::Mesh &)node);
   851                      continue;
   852                  }
   853                  // mesh material index
   854                  if (TokenMatch(filePtr, "MATERIAL_REF", 12)) {
   855                      ParseLV4MeshLong(((ASE::Mesh &)node).iMaterialIndex);
   856                      continue;
   857                  }
   858              }
   859          }
   860          AI_ASE_HANDLE_TOP_LEVEL_SECTION();
   861      }
   862      return;
   863  }
