  1195  void Parser::ParseLV2MeshBlock(ASE::Mesh &mesh) {
  1196      AI_ASE_PARSER_INIT();
  1197
  1198      unsigned int iNumVertices = 0;
  1199      unsigned int iNumFaces = 0;
  1200      unsigned int iNumTVertices = 0;
  1201      unsigned int iNumTFaces = 0;
  1202      unsigned int iNumCVertices = 0;
  1203      unsigned int iNumCFaces = 0;
  1204      while (true) {
  1205          if ('*' == *filePtr) {
  1206              ++filePtr;
  1207              // Number of vertices in the mesh
  1208              if (TokenMatch(filePtr, "MESH_NUMVERTEX", 14)) {
  1209                  ParseLV4MeshLong(iNumVertices);
  1210                  continue;
  1211              }
  1212              // Number of texture coordinates in the mesh
  1213              if (TokenMatch(filePtr, "MESH_NUMTVERTEX", 15)) {
  1214                  ParseLV4MeshLong(iNumTVertices);
  1215                  continue;
  1216              }
  1217              // Number of vertex colors in the mesh
  1218              if (TokenMatch(filePtr, "MESH_NUMCVERTEX", 15)) {
  1219                  ParseLV4MeshLong(iNumCVertices);
  1220                  continue;
  1221              }
  1222              // Number of regular faces in the mesh
  1223              if (TokenMatch(filePtr, "MESH_NUMFACES", 13)) {
  1224                  ParseLV4MeshLong(iNumFaces);
  1225                  continue;
  1226              }
  1227              // Number of UVWed faces in the mesh
  1228              if (TokenMatch(filePtr, "MESH_NUMTVFACES", 15)) {
  1229                  ParseLV4MeshLong(iNumTFaces);
  1230                  continue;
  1231              }
  1232              // Number of colored faces in the mesh
  1233              if (TokenMatch(filePtr, "MESH_NUMCVFACES", 15)) {
  1234                  ParseLV4MeshLong(iNumCFaces);
  1235                  continue;
  1236              }
  1237              // mesh vertex list block
  1238              if (TokenMatch(filePtr, "MESH_VERTEX_LIST", 16)) {
  1239                  ParseLV3MeshVertexListBlock(iNumVertices, mesh);
  1240                  continue;
  1241              }
  1242              // mesh face list block
  1243              if (TokenMatch(filePtr, "MESH_FACE_LIST", 14)) {
  1244                  ParseLV3MeshFaceListBlock(iNumFaces, mesh);
  1245                  continue;
  1246              }
  1247              // mesh texture vertex list block
  1248              if (TokenMatch(filePtr, "MESH_TVERTLIST", 14)) {
  1249                  ParseLV3MeshTListBlock(iNumTVertices, mesh);
  1250                  continue;
  1251              }
  1252              // mesh texture face block
  1253              if (TokenMatch(filePtr, "MESH_TFACELIST", 14)) {
  1254                  ParseLV3MeshTFaceListBlock(iNumTFaces, mesh);
  1255                  continue;
  1256              }
  1257              // mesh color vertex list block
  1258              if (TokenMatch(filePtr, "MESH_CVERTLIST", 14)) {
  1259                  ParseLV3MeshCListBlock(iNumCVertices, mesh);
  1260                  continue;
  1428              ++filePtr;
  1429
  1430              // Vertex entry
  1431              if (TokenMatch(filePtr, "MESH_VERTEX", 11)) {
  1432
  1433                  aiVector3D vTemp;
  1434                  unsigned int iIndex;
  1435                  ParseLV4MeshFloatTriple(&vTemp.x, iIndex);
  1436
  1437                  if (iIndex >= iNumVertices) {
  1438                      LogWarning("Invalid vertex index. It will be ignored");
