   698      // Reset the third color set to nullptr - we used this field to store a temporary pointer
   699      for (unsigned int i = 0; i < pcScene->mNumMeshes; ++i)
   700          pcScene->mMeshes[i]->mColors[2] = nullptr;
   701
   702      // The root node should not have at least one child or the file is valid
   703      if (!pcScene->mRootNode->mNumChildren) {
   704          throw DeadlyImportError("ASE: No nodes loaded. The file is either empty or corrupt");
   705      }
   706
   707      // Now rotate the whole scene 90 degrees around the x axis to convert to internal coordinate system
   708      pcScene->mRootNode->mTransformation = aiMatrix4x4(1.f, 0.f, 0.f, 0.f,
   709              0.f, 0.f, 1.f, 0.f, 0.f, -1.f, 0.f, 0.f, 0.f, 0.f, 0.f, 1.f);
   710  }
